#!/usr/bin/env python3
"""Add the screenshot extension to the generated XcodeGen project.

Run after ios-project.py, before xcodegen. Requires PyYAML 6.0.3.
Unsigned mode is for simulator/compile validation, never distribution.
"""
import argparse
import os
from pathlib import Path
import plistlib
import yaml

GROUP = 'group.nl.sbvh.qntx'
EXTENSION = 'QNTXShare'
BUNDLE = 'nl.sbvh.qntx.share'


def configure(path, version, build, team='', profile='', unsigned=False):
    path = Path(path).resolve()
    root = Path(__file__).resolve().parents[2]
    project = yaml.safe_load(path.read_text())
    targets = project['targets']
    apps = [target for target in targets.values()
            if target.get('type') == 'application' and target.get('platform') == 'iOS']
    if len(apps) != 1:
        raise ValueError('Expected exactly one iOS application target')
    if not unsigned and (not team or not profile):
        raise ValueError('APPLE_DEVELOPMENT_TEAM and SHARE_PROVISIONING_PROFILE are required')
    app = apps[0]
    # Preserve existing entitlements, including ones generated by Tauri.
    base = app.setdefault('settings', {}).setdefault('base', {})
    entitlement_spec = app.get('entitlements', {})
    existing = entitlement_spec.get('path') or base.get('CODE_SIGN_ENTITLEMENTS')
    properties = {}
    if existing:
        existing_path = path.parent / existing
        if existing_path.exists():
            properties.update(plistlib.loads(existing_path.read_bytes()))
        elif not entitlement_spec:
            raise ValueError(f'Cannot read existing entitlements: {existing_path}')
    properties.update(entitlement_spec.get('properties', {}))
    groups = properties.setdefault('com.apple.security.application-groups', [])
    if GROUP not in groups:
        groups.append(GROUP)
    app['entitlements'] = {'path': 'QNTXShareHost.entitlements', 'properties': properties}
    base['CODE_SIGN_ENTITLEMENTS'] = 'QNTXShareHost.entitlements'
    deps = app.setdefault('dependencies', [])
    if not any(d.get('target') == EXTENSION for d in deps):
        deps.append({'target': EXTENSION, 'embed': True})
    relative = lambda p: os.path.relpath(root / p, path.parent)
    project.setdefault('packages', {})['InboxCore'] = {'path': relative('share/ios/InboxCore')}
    settings = {
        'PRODUCT_BUNDLE_IDENTIFIER': BUNDLE,
        'SWIFT_VERSION': '5.0',
        'APPLICATION_EXTENSION_API_ONLY': 'YES',
        'SKIP_INSTALL': 'YES',
        'MARKETING_VERSION': str(version),
        'CURRENT_PROJECT_VERSION': str(build),
        'TARGETED_DEVICE_FAMILY': '1,2',
        'INFOPLIST_FILE': relative('share/extension/Info.plist'),
        'CODE_SIGN_ENTITLEMENTS': relative('share/extension/Share.entitlements'),
    }
    if unsigned:
        settings['CODE_SIGNING_ALLOWED'] = 'NO'
    else:
        settings.update(CODE_SIGN_STYLE='Manual', DEVELOPMENT_TEAM=team,
                        PROVISIONING_PROFILE_SPECIFIER=profile, CODE_SIGN_IDENTITY='Apple Distribution')
    targets[EXTENSION] = {
        'type': 'app-extension', 'platform': 'iOS', 'deploymentTarget': '15.0',
        'sources': [{'path': relative('share/extension/ShareViewController.swift')}],
        'dependencies': [{'package': 'InboxCore'}, {'sdk': 'Social.framework'}, {'sdk': 'ImageIO.framework'}],
        'settings': {'base': settings},
    }
    path.write_text(yaml.safe_dump(project, sort_keys=False))


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('project')
    parser.add_argument('--version', required=True)
    parser.add_argument('--build', required=True)
    parser.add_argument('--unsigned', action='store_true')
    args = parser.parse_args()
    if not args.unsigned:
        host_profile = os.environ['PROVISIONING_PROFILE']
        if not host_profile:
            raise ValueError('PROVISIONING_PROFILE is required for IPA export')
    configure(args.project, args.version, args.build, os.environ.get('APPLE_DEVELOPMENT_TEAM', ''),
              os.environ.get('SHARE_PROVISIONING_PROFILE', ''), args.unsigned)
    if not args.unsigned:
        export = {
            'method': 'app-store-connect', 'signingStyle': 'manual',
            'teamID': os.environ['APPLE_DEVELOPMENT_TEAM'],
            'signingCertificate': 'Apple Distribution',
            'provisioningProfiles': {
                'nl.sbvh.qntx': host_profile,
                BUNDLE: os.environ['SHARE_PROVISIONING_PROFILE'],
            },
        }
        Path(args.project).with_name('ShareExportOptions.plist').write_bytes(plistlib.dumps(export))
